pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address account) public {
        vm.assume(account != address(0));
        // Setup: ensure account is not blacklisted initially
        vm.assume(!c.blacklist(account));
        // Ensure enough tokens remain for distribution
        uint256 remaining = c.totalRemaining();
        uint256 val = c.value();
        vm.assume(val <= remaining);
        // Call XBornID() as the owner to set up initial distribution
        vm.prank(c.owner());
        c.XBornID();
        // Now call getTokens as the fuzzed address
        // We need to provide enough value so that toGive > 0 (value is non-zero in contract, but ensure)
        vm.assume(c.value() > 0);
        vm.prank(account);
        c.getTokens();
        // After the call, if toGive > 0, then blacklist[account] should be true
        // Since value > 0 and totalRemaining >= value, toGive = value > 0
        assertTrue(c.blacklist(account) == true);
    }
}

