pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnValue) public {
        // Bound burnValue to be <= totalDistributed (200000000e18) so it doesn't underflow totalDistributed
        vm.assume(burnValue <= 200000000e18);

        // Record initial totalSupply
        uint256 initialTotalSupply = c.totalSupply();

        // Call burn through the owner
        vm.prank(address(this)); // owner is msg.sender of deployment
        // But we need to make sure caller has enough balance; let's use the owner's address which got totalDistributed in constructor
        // Actually the constructor assigns balances[owner] = totalDistributed in XBornID(), but we haven't called it yet.
        // Let's call XBornID() first to set up balances
        c.XBornID();

        // Now owner has balance = totalDistributed
        // But we need to ensure burnValue <= owner's balance; we already assumed burnValue <= totalDistributed
        // Also need to ensure totalDistributed - burnValue doesn't underflow; already satisfied.

        vm.prank(address(this));
        c.burn(burnValue);

        // Call XBornID() again as required by the difference description
        c.XBornID();

        // General rule: after XBornID(), totalSupply should equal initialTotalSupply - burnValue
        // (since burn subtracts, and XBornID doesn't change totalSupply)
        uint256 expectedTotalSupply = initialTotalSupply - burnValue;
        assertTrue(c.totalSupply() == expectedTotalSupply, "totalSupply should decrease by burnValue");
    }
}

